def giro_page(g):
    path = f"/ciberseguridad-para-{g['slug']}/"
    title = f"Ciberseguridad para {g['name']} · Inspector Hacker"
    body = [
        (f"Qué le pasa a {g['name']} cuando nadie vigila", g["riesgos"]),
        ("Qué vigilamos en tu giro", ["<ul>" + "".join(f"<li>{x}</li>" for x in g["vigilamos"]) + "</ul>", METODO]),
        ("Lo que encontramos en el Arranque", [g["caso"], PLANES]),
    ]
    faq = g["faq"] + FAQ_COMUN
    related = [(f"/ciberseguridad-para-{x['slug']}/", "Ciberseguridad para " + x["name"][:1].upper() + x["name"][1:], "Por giro") for x in GIROS if x is not g][:6]
    grid = related + [("/industrias/", "Todos los giros", "15 sectores"), ("/guias/", "Guías", "Pentest, ransomware, LFPDPPP…"), ("/ciudades/", "Ciudades", "34 ciudades de México"), ("/planes/", "Planes y precios", "Arranque, Vigía, Vigía Plus")]
    return dict(path=path, L=ES, kind="local", published=PUB, crumbs=[("Giros", "/industrias/")],
                title=title, desc=g["desc"], kick="Ciberseguridad con IA · por giro", h1=g["h1"],
                sub=f"Vigilancia continua con IA para {g['name']} en todo México: lo que tienes expuesto a internet, tu correo, tus servidores y tu código revisados cada semana, con reporte mensual para Dirección. Sin pentest caro.",
                service_name=f"Vigilancia de ciberseguridad con IA para {g['name']}", body=body, faq=faq,
                grid=grid, grid_extra=[], grid_lab="También te sirve", grid_h2="Otros giros y páginas relacionadas")

