def guia_page(g):
    path = f"/guias/{g['slug']}/"
    related = [(f"/guias/{x['slug']}/", strip_tags(x["h1"])[:60], "Guía") for x in GUIAS if x is not g]
    grid = related + [("/guias/", "Todas las guías", "Índice"), ("/industrias/", "Ciberseguridad por giro", "15 sectores"), ("/planes/", "Planes y precios", "Arranque, Vigía, Vigía Plus"), ("/vigilancia-vs-pentest/", "Vigilancia vs pentest", "Cuándo conviene cada una")]
    return dict(path=path, L=ES, kind="article", article_type="Article", og_type="article", published=PUB, crumbs=[("Guías", "/guias/")],
                title=g["title"], desc=g["desc"], kick=g["kick"] + " · Inspector Hacker", h1=g["h1"],
                sub="Escrito por el equipo de Inspector Hacker con lo que vemos en pymes mexicanas. Cifras y precios con fuente; sin relleno.",
                body=g["body"], faq=g["faq"], grid=grid, grid_extra=[], grid_lab="Seguir leyendo", grid_h2="Otras guías y páginas relacionadas")

